#include <vector>
#include <algorithm>

using namespace std;

class TwoPointerTemplate {
public:
    // Core structural setup for an inward converging two-pointer strategy
    vector<int> findTargetPair(vector<int>& nums, int target) {
        // Enforce ordering constraint up-front if input is not pre-sorted
        sort(nums.begin(), nums.end());

        int start = 0;
        int end = nums.size() - 1;

        while (start < end) {
            int currentSum = nums[start] + nums[end];

            if (currentSum == target) {
                return {start, end}; // Target hit
            }

            if (currentSum < target) {
                // Sum is too small -> expand upwards from the left
                start++;
            } else {
                // Sum is too large -> compress downwards from the right
                end--;
            }
        }

        return {-1, -1}; // No valid target pair discovered
    }
};

